code.cpp:
class Solution {
public:
    int countCharacters(vector<string>& words, string chars) {
        int cnt[26] = {0};
        for (char c : chars) cnt[c - 'a']++;
        int ans = 0;
        for (const string& w : words) {
            int wc[26] = {0};
            for (char c : w) wc[c - 'a']++;
            bool ok = true;
            for (int i = 0; i < 26; i++) {
                if (wc[i] > cnt[i]) { ok = false; break; }
            }
            if (ok) ans += (int)w.size();
        }
        return ans;
    }
};
